"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["75524"],{93878(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.regra_de_comprovacao.reenvio_proibido_em_regra_de_documento","status":422,"titulo":"A regra de documento n\xe3o declara reenvio pr\xf3prio; o reenvio \xe9 declarado na exig\xeancia"},"descricao":{"codigo":"uniplus.selecao.regra_de_comprovacao.reenvio_proibido_em_regra_de_documento","requisitos":["UNI-REQ-0520"],"oQueAconteceu":["Uma regra de documento declarou `indeferimento.abrePrazoParaReenvio` como verdadeiro. A regra de documento n\xe3o tem indeferimento pr\xf3prio: o reenvio pertence \xe0 exig\xeancia do documento, em `documento.indeferimento.abrePrazoParaReenvio`, e o grupo de comprova\xe7\xe3o declara o reenvio no `indeferimento` dele. Sem a recusa, a declara\xe7\xe3o seria descartada e a leitura seguinte n\xe3o a traria de volta.","O campo da resposta \xe9 `regrasDeComprovacao[i].indeferimento.abrePrazoParaReenvio`, com a posi\xe7\xe3o da regra, e as demais recusas do pedido v\xeam na mesma resposta. Nada \xe9 gravado."],"comoResolver":["Retire `abrePrazoParaReenvio` do `indeferimento` da regra de documento. Para abrir prazo de reenvio dessa exig\xeancia, declare `abrePrazoParaReenvio` em `documento.indeferimento`."],"ondeAparece":["Defini\xe7\xe3o dos documentos exigidos do processo seletivo."]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Regra de comprovacao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);